 public sealed class MalwHostsService {public string Name;public List<string> Entries=new List<string>();}
 public static class MalwHosts {
  const string Begin="# MCRF MALW BEGIN",End="# MCRF MALW END";
  static bool Dedicated(string domain){return HostsCandidates.AllowedDomain("instagram",domain)||HostsCandidates.AllowedDomain("chatgpt",domain);}
  public static List<MalwHostsService> Catalog(string text){
   if(text==null||text.Length>10*1024*1024)throw new FormatException("Некорректный размер списка ImMALWARE.");var result=new List<MalwHostsService>();string section=null;
   foreach(string raw in text.Split('\n')){var line=raw.Trim();if(line.StartsWith("#")){string title=line.TrimStart('#').Trim();if(title.IndexOf("Блокировка",StringComparison.OrdinalIgnoreCase)>=0)break;if(!String.IsNullOrEmpty(title)&&!title.Contains("hosts file")&&!title.StartsWith("Последнее обновление"))section=title;continue;}var fields=line.Split('#')[0].Split(new[]{' ','\t','\r'},StringSplitOptions.RemoveEmptyEntries);if(fields.Length<2)continue;if(!HostsCandidates.PublicV4(fields[0]))continue;foreach(var value in fields.Skip(1)){string domain=value.ToLowerInvariant();if(Dedicated(domain))continue;Validate(fields[0],domain);string name=section??domain;var group=result.FirstOrDefault(g=>g.Name==name);if(group==null){group=new MalwHostsService{Name=name};result.Add(group);}string entry=fields[0]+" "+domain;if(!group.Entries.Contains(entry))group.Entries.Add(entry);}}
   if(result.Count==0)throw new FormatException("В источнике нет доступных сервисов.");return result;
  }
  static void Validate(string ip,string domain){if(!HostsCandidates.PublicV4(ip)||!Regex.IsMatch(domain,@"^(?=.{1,253}$)[a-z0-9]+(?:[a-z0-9.-]*[a-z0-9])?$")||domain.Contains("..")||!domain.Contains(".")||Dedicated(domain))throw new FormatException("Некорректная запись или домен из отдельных блоков Instagram/ChatGPT: "+domain);}
  public static string ValidateEntries(string text){var entries=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string raw in (text??"").Split('\n')){var fields=raw.Split('#')[0].Trim().Split(new[]{' ','\t','\r'},StringSplitOptions.RemoveEmptyEntries);if(fields.Length==0)continue;if(fields.Length<2)throw new FormatException("Формат hosts: IP домен.");foreach(string domain in fields.Skip(1)){string name=domain.ToLowerInvariant();Validate(fields[0],name);if(entries.ContainsKey(name)&&entries[name]!=fields[0])throw new FormatException("Разные IP для "+name);entries[name]=fields[0];}}if(entries.Count>1000)throw new FormatException("Слишком много записей.");return String.Join("\r\n",entries.Select(p=>p.Value+" "+p.Key));}
  static Match Block(string managed){var match=Regex.Match(managed,@"(?ms)^# MCRF MALW BEGIN\r*\n(.*?)^# MCRF MALW END\r*$" );if((managed.Contains(Begin)||managed.Contains(End))&&!match.Success||Regex.Matches(managed,Regex.Escape(Begin)).Count>1||Regex.Matches(managed,Regex.Escape(End)).Count>1)throw new IOException("Повреждён блок дополнительных сервисов hosts.");return match;}
  public static string Entries(byte[] original){var match=Block(HostsEditor.Managed(original));return match.Success?match.Groups[1].Value.Trim():"";}
  public static byte[] Compose(byte[] original,string text){string entries=ValidateEntries(text);string managed=HostsEditor.Managed(original);var match=Block(managed);if(match.Success)managed=managed.Remove(match.Index,match.Length);var domains=new HashSet<string>(entries.Split('\n').Where(l=>l.Contains(" ")).Select(l=>l.Trim().Split(' ')[1]),StringComparer.OrdinalIgnoreCase);string remaining=Encoding.UTF8.GetString(HostsRepair.Compose(original,managed));foreach(string raw in remaining.Split('\n')){var fields=raw.Split('#')[0].Trim().Split(new[]{' ','\t','\r'},StringSplitOptions.RemoveEmptyEntries);if(fields.Skip(1).Any(domains.Contains))throw new IOException("Домен уже внесён другим блоком hosts. Сначала уберите конфликтующую запись.");}return HostsRepair.Compose(original,managed.Trim()+ (entries.Length==0?"":"\r\n"+Begin+"\r\n"+entries+"\r\n"+End));}
 }
 public sealed class HostsTrial : IDisposable {
  readonly string root;readonly byte[] before,after;bool applied;
  public HostsTrial(string root,string service,List<HostsCandidate> hosts){this.root=root;before=HostsRepair.ReadHostsFile(HostsEditor.PathName);after=HostsEditor.Compose(before,HostsCandidates.Entries(hosts),service);HostsRepair.Apply(root,HostsEditor.Managed(after),before);applied=true;}
  public void Dispose(){if(!applied)return;HostsRepair.Apply(root,HostsEditor.Managed(before),after,false);applied=false;}
 }
 public static class HostsEditor {
  public static string PathName{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"drivers","etc","hosts");}}
  public static string Managed(byte[] original){HostsRepair.Compose(original,null);var text=Encoding.UTF8.GetString(original);var match=Regex.Match(text,@"(?ms)^# MCRF META BEGIN\r?\n(.*?)^# MCRF META END");return match.Success?match.Groups[1].Value:"";}
  public static List<HostsCandidate> Parse(string text,string service){if(String.IsNullOrWhiteSpace(text))return new List<HostsCandidate>();return HostsCandidates.ParseLines(text,service,"Ручной редактор",true);}
  public static void UpdateProfileEntries(IEnumerable<ZapretProfile> profiles,string service,string text,bool replacedOwner){var entries=Parse(text,service);foreach(var profile in profiles){bool had=(profile.Settings.Hosts??new List<HostsCandidate>()).Any(h=>h.Service==service);if(!had&&!replacedOwner)continue;profile.Settings.Hosts=(profile.Settings.Hosts??new List<HostsCandidate>()).Where(h=>h.Service!=service).ToList();if(had&&!replacedOwner)profile.Settings.Hosts.AddRange(entries);}}
  public static string ServiceEntries(byte[] original,string service){string managed=Managed(original);var lines=managed.Split('\n').Select(l=>{var fields=l.Split('#')[0].Trim().Split(new[]{' ','\t','\r'},StringSplitOptions.RemoveEmptyEntries);return fields.Length<2?"":fields[0]+" "+String.Join(" ",fields.Skip(1).Where(d=>HostsCandidates.AllowedDomain(service,d.ToLowerInvariant())));}).Where(l=>l.Trim().Contains(" ")).ToArray();return lines.Length==0?"":HostsCandidates.Entries(Parse(String.Join("\n",lines),service));}
  static string RetainOtherService(string line,string service){
   int commentAt=line.IndexOf('#');string comment=commentAt<0?"":line.Substring(commentAt);string record=commentAt<0?line:line.Substring(0,commentAt);
   var words=record.Trim().Split(new[]{' ','\t','\r'},StringSplitOptions.RemoveEmptyEntries);
   if(words.Length<2||!words.Skip(1).Any(d=>HostsCandidates.AllowedDomain(service,d.ToLowerInvariant())))return line;
   var remaining=words.Skip(1).Where(d=>!HostsCandidates.AllowedDomain(service,d.ToLowerInvariant())).ToArray();
   return remaining.Length==0?comment:words[0]+" "+String.Join(" ",remaining)+(comment.Length==0?"":" "+comment);
  }
  public static byte[] Compose(byte[] original,string text,string service){
   var selected=Parse(text,service);string entries=HostsCandidates.Entries(selected);
   var other=Managed(original).Split('\n').Select(l=>RetainOtherService(l,service));
   string outside=Encoding.UTF8.GetString(HostsRepair.Compose(original,null));
   foreach(var item in selected)if(Regex.IsMatch(outside,@"(?im)^\s*[^#\r\n]+\s"+Regex.Escape(item.Domain)+@"(?:\s|$)"))throw new InvalidOperationException("Вне блока MCRF уже есть запись "+item.Domain+". Она не будет перезаписана.");
   return HostsRepair.Compose(original,String.Join("\r\n",other.Where(l=>!String.IsNullOrWhiteSpace(l)))+"\r\n"+entries);
  }
 }
