   var description=L("hosts связывает домен с указанным IP. Это не VPN. Меняем только записи выбранного сервиса в блоке MCRF; остальные записи сохраняются. Перед изменением создаётся резервная копия.",11,false,Muted);description.AutoSize=false;description.SetBounds(22,16,box.Width-44,62);box.Controls.Add(description);
   var services=new GlassPicker{Name="hostsService",Location=new Point(22,88),Width=260};services.SetItems(new[]{"Instagram / Facebook","ChatGPT","Rutor"});box.Controls.Add(services);string[] ids={"instagram","chatgpt","rutor"};
   var source=new GlassPicker{Name="hostsSourcePicker",Location=new Point(300,88),Width=Math.Max(240,box.Width-322)};source.SetItems(new[]{"Zapret-Manager","dns.malw.link","GeoHideDNS"});source.SelectedIndex=0;box.Controls.Add(source);
   var warning=L("",10,false,Color.FromArgb(255,220,110));warning.AutoSize=false;warning.SetBounds(22,142,box.Width-44,55);box.Controls.Add(warning);
   var editor=new TextBox{Name="hostsEditableEntries",Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,BorderStyle=BorderStyle.FixedSingle,BackColor=GlassFieldPanel.InputColor,ForeColor=Ink,Font=Font};editor.SetBounds(22,203,box.Width-44,Math.Max(90,box.Height-365));editor.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;box.Controls.Add(editor);
   var status=L("Формат: IP домен, одна запись на строке.",10,false,Muted);status.AutoSize=false;status.SetBounds(22,box.Height-155,box.Width-44,60);status.Anchor=AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;box.Controls.Add(status);
   bool busy=false;CancellationTokenSource cancellation=null;string id="instagram";
   Action load=()=>{if(busy)return;id=ids[Math.Max(0,services.SelectedIndex)];try{editor.Text=HostsEditor.ServiceEntries(File.ReadAllBytes(HostsEditor.PathName),id);}catch(Exception ex){status.Text=ex.Message;}
    warning.Text=id=="chatgpt"?"ChatGPT: в источниках встречаются сторонние SNI-реле. Это не IP OpenAI. Не отключаем TLS и не устанавливаем чужие сертификаты. Проверка HTTP не подтверждает вход и отправку сообщения.":"Альтернативный IP может помочь вместе с Zapret, но не гарантирует загрузку медиа. Проверьте изображения, видео и вход самостоятельно.";};
   services.SelectedIndexChanged+=(s,e)=>load();services.SelectedIndex=0;
   Action<bool> enabled=value=>{busy=!value;services.Enabled=source.Enabled=editor.Enabled=value;};
   var fetch=B("Подобрать IP",async(s,e)=>{if(busy)return;enabled(false);cancellation=new CancellationTokenSource();try{
    string url=source.SelectedIndex==0?HostsRepair.Source:source.SelectedIndex==1?HostsCandidates.MalwSource:"https://raw.githubusercontent.com/Internet-Helper/GeoHideDNS/main/hosts/hosts";status.Text="Загружаем источник…";var raw=await core.DownloadTextAsync(url);cancellation.Token.ThrowIfCancellationRequested();var candidates=source.SelectedIndex==0?HostsCandidates.ParseScript(raw,id):HostsCandidates.ParseLines(raw,id,url);
    status.Text="Проверяем TLS и HTTP всех адресов без изменения hosts…";var results=await HostsCandidates.ProbeAll(core,candidates,cancellation.Token,r=>{if(!status.IsDisposed)status.Text=r.Candidate.Domain+" → "+r.Candidate.Address+" · "+r.Detail;});
    var best=results.Where(r=>r.Usable).GroupBy(r=>r.Candidate.Domain).Select(g=>g.OrderBy(r=>r.Milliseconds).First().Candidate).ToArray();if(best.Length==0)throw new InvalidOperationException("Ни один адрес не подтвердил TLS/HTTP. Текущие записи не изменены.");
    if(!editor.IsDisposed)editor.Text=HostsCandidates.Entries(best);if(!status.IsDisposed)status.Text="Подобрано доменов: "+best.Length+". TLS/HTTP проверен дважды. Это ещё не подтверждение работы сервиса. Записи НЕ сохранены; их можно отредактировать.";
   }catch(OperationCanceledException){if(!status.IsDisposed)status.Text="Подбор отменён; hosts не изменён.";}catch(Exception ex){if(!status.IsDisposed)status.Text=ex.Message;}finally{cancellation.Dispose();cancellation=null;if(!box.IsDisposed)enabled(true);}});fetch.Name="hostsPick";fetch.SetBounds(22,box.Height-88,190,36);fetch.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;box.Controls.Add(fetch);
   var check=B("Проверить записи",async(s,e)=>{if(busy)return;enabled(false);cancellation=new CancellationTokenSource();try{var entries=HostsEditor.Parse(editor.Text,id);HostsCandidates.Entries(entries);if(entries.Count==0)throw new InvalidOperationException("Введите записи.");var results=await HostsCandidates.ProbeAll(core,entries,cancellation.Token,null);status.Text=String.Join(" · ",results.Select(r=>r.Candidate.Domain+": "+(r.Usable?"TLS/HTTP доступен":"не подтверждён")));}catch(Exception ex){if(!status.IsDisposed)status.Text=ex.Message;}finally{cancellation.Dispose();cancellation=null;if(!box.IsDisposed)enabled(true);}});check.Name="hostsCheck";check.SetBounds(228,box.Height-88,210,36);check.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;box.Controls.Add(check);
   var apply=B("Сохранить записи",async(s,e)=>{if(busy)return;try{var original=File.ReadAllBytes(HostsEditor.PathName);var next=HostsEditor.Compose(original,editor.Text,id);if(!IsAdministrator())throw new InvalidOperationException("Перезапустите MCRF с правами администратора. Ничего не изменено.");if(!await ConfirmChange("Сохранить показанные записи выбранного сервиса? Работу сайта необходимо проверить в браузере. Остальные записи сохранятся; резервная копия будет в hosts-backups.","Сохранить hosts","Изменение hosts"))return;enabled(false);await System.Threading.Tasks.Task.Run(()=>HostsRepair.Apply(store.Root,HostsEditor.Managed(next),original));status.Text="Сохранено. Перезапустите браузер и проверьте сервис.";}catch(Exception ex){if(!status.IsDisposed)status.Text=ex.Message;}finally{if(!box.IsDisposed)enabled(true);}},true);apply.Name="hostsSave";apply.SetBounds(22,box.Height-44,220,36);apply.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;box.Controls.Add(apply);
   var remove=B("Убрать записи сервиса",async(s,e)=>{if(busy)return;try{if(!await ConfirmChange("Удалить только записи "+services.SelectedItem+" из блока MCRF? Другие записи сохранятся.","Убрать записи"))return;var original=File.ReadAllBytes(HostsEditor.PathName);var next=HostsEditor.Compose(original,"",id);enabled(false);await System.Threading.Tasks.Task.Run(()=>HostsRepair.Apply(store.Root,HostsEditor.Managed(next),original));status.Text="Записи сервиса удалены. Другие записи сохранены.";enabled(true);load();}catch(Exception ex){if(!status.IsDisposed)status.Text=ex.Message;}finally{if(!box.IsDisposed)enabled(true);}});remove.Name="hostsRemoveService";remove.SetBounds(260,box.Height-44,260,36);remove.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;box.Controls.Add(remove);
   var stop=B("Отмена подбора",(s,e)=>{if(cancellation!=null)cancellation.Cancel();});stop.SetBounds(454,box.Height-88,210,36);stop.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;box.Controls.Add(stop);box.Disposed+=(s,e)=>{if(cancellation!=null)cancellation.Cancel();};
  }
 }
